int kvm_update_pit_state(struct kvm *kvm, struct kvm_pit_state2 *ps) {
    int i;

    mutex_lock(&kvm->pit_state->mutex);
    kvm->pit_state->hpet = ps->hpet;
    for (i = 0; i < 3; i++) {
        kvm->pit_state->channels[i].count = le32_to_cpu(ps->channels[i].count);
        kvm->pit_state->channels[i].latch = le32_to_cpu(ps->channels[i].latch);
        kvm->pit_state->channels[i].mode = ps->channels[i].mode;
        kvm->pit_state->channels[i].initial_count = le32_to_cpu(ps->channels[i].initial_count);
        kvm->pit_state->channels[i].initial_mode = ps->channels[i].initial_mode;
        kvm->pit_state->channels[i].status = ps->channels[i].status;
        kvm->pit_state->channels[i].init_count = le32_to_cpu(ps->channels[i].init_count);
    }
    mutex_unlock(&kvm->pit_state->mutex);

    return 0;
}
